-- Notification channels (NOTIFY-001, CONTEXT_PACK §7, §8.6, §8.7). Generated by `pnpm db:generate` from
-- src/schema/notifications.ts, then reviewed. Forward-only: never edit once applied; add a new migration.
-- `config` holds non-secret settings only; `secret_ref` is the opaque bw-secret:// URI of the credential, never its value.
CREATE TABLE "notification_channels" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"name" text NOT NULL,
	"config" jsonb DEFAULT '{}'::jsonb NOT NULL,
	"secret_ref" text,
	"status" text DEFAULT 'active' NOT NULL,
	"created_by" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "notification_channels_name_check" CHECK (length("notification_channels"."name") BETWEEN 1 AND 120 AND "notification_channels"."name" IS NFC NORMALIZED AND "notification_channels"."name" !~ '[[:cntrl:]]' AND btrim("notification_channels"."name") <> ''),
	CONSTRAINT "notification_channels_kind_check" CHECK ("notification_channels"."kind" IN ('email', 'slack', 'teams', 'webhook', 'pagerduty', 'opsgenie')),
	CONSTRAINT "notification_channels_status_check" CHECK ("notification_channels"."status" IN ('active', 'disabled')),
	CONSTRAINT "notification_channels_config_object_check" CHECK (jsonb_typeof("notification_channels"."config") = 'object'),
	CONSTRAINT "notification_channels_no_credential_check" CHECK (NOT ("notification_channels"."config" ?| array['secret', 'token', 'password', 'api_key', 'apikey', 'routing_key', 'webhook_url', 'hmac_key'])),
	CONSTRAINT "notification_channels_secret_ref_check" CHECK ("notification_channels"."secret_ref" IS NULL OR starts_with("notification_channels"."secret_ref", 'bw-secret://' || "notification_channels"."tenant_id"::text || '/')),
	CONSTRAINT "notification_channels_secret_presence_check" CHECK (("notification_channels"."kind" = 'email') = ("notification_channels"."secret_ref" IS NULL))
);
--> statement-breakpoint
ALTER TABLE "notification_channels" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE UNIQUE INDEX "notification_channels_tenant_name_idx" ON "notification_channels" USING btree ("tenant_id","name");--> statement-breakpoint
CREATE INDEX "notification_channels_tenant_id_idx" ON "notification_channels" USING btree ("tenant_id");--> statement-breakpoint
CREATE POLICY "notification_channels_tenant_isolation" ON "notification_channels" AS PERMISSIVE FOR ALL TO public USING (tenant_id = current_setting('app.tenant_id')::uuid) WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);
--> statement-breakpoint
-- Hand-written (Drizzle does not model these): FORCE RLS for the owner role too, grants for the runtime role (a channel
-- is disabled, never deleted: no DELETE), and the updated_at trigger (bw_set_updated_at: 0002_column_mixins).
ALTER TABLE "notification_channels" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
REVOKE ALL ON "notification_channels" FROM PUBLIC;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "notification_channels" TO bw_app;--> statement-breakpoint
REVOKE DELETE, TRUNCATE ON "notification_channels" FROM bw_app;--> statement-breakpoint
CREATE TRIGGER notification_channels_set_updated_at BEFORE UPDATE ON notification_channels FOR EACH ROW EXECUTE FUNCTION bw_set_updated_at();
